import sys
import logging

logging.basicConfig(stream=sys.stdout, format="%(levelname)s:%(message)s", level=logging.INFO)

筐数 = int(input())

for i in range(筐数):
    一条 = int(input())
    if 一条 < 3:
        logging.error("第 " + str(i + 1) + " {unit}告急：" + str(一条) + " 条")
    elif 一条 < 7:
        logging.warning("第 " + str(i + 1) + " {unit}偏少：" + str(一条) + " 条")
    else:
        logging.info("第 " + str(i + 1) + " {unit}充足：" + str(一条) + " 条")

print("一共 " + str(筐数) + " {unit}")
